import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long next() {
        while (buf[pos] != '-' && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long x = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') x = x * 10 + (buf[pos++] - '0');
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        long q = next();
        long minR = Long.MAX_VALUE, minC = Long.MAX_VALUE;
        for (long i = 0; i < q; i++) {
            minR = Math.min(minR, next());
            minC = Math.min(minC, next());
        }
        // Every operation covers [1..r]x[1..c]; the cells covered by all operations hold the maximum.
        System.out.println(minR * minC);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"math"
	"os"
)

var data []byte
var pos int

func next() int64 {
	for data[pos] != '-' && (data[pos] < '0' || data[pos] > '9') {
		pos++
	}
	neg := data[pos] == '-'
	if neg {
		pos++
	}
	var x int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		x = x*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -x
	}
	return x
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	q := next()
	minR, minC := int64(math.MaxInt64), int64(math.MaxInt64)
	for i := int64(0); i < q; i++ {
		minR = min(minR, next())
		minC = min(minC, next())
	}
	// Every operation covers [1..r]x[1..c]; the cells covered by all operations hold the maximum.
	fmt.Println(minR * minC)
